+		while (index !== -1) {
+			const next = stack[index + candidate.length];
+			// Require a boundary so /plugins/foo does not match /plugins/foobar.
+			if (
+				next === undefined ||
+				next === sep ||
+				next === "/" ||
+				next === ":" ||
+				next === ")" ||
+				next === "?" ||
+				/\s/.test(next)
