+			rejectPromise(new PluginCallTimeoutError(label, timeoutMs));
+		}, timeoutMs);
+		timer.unref?.();
+		Promise.resolve()
+			.then(fn)
+			.then(
+				(value) => {
+					if (settled) return;
+					settled = true;
+					clearTimeout(timer);
+					resolvePromise(value);
+				},
+				(error) => {
